export function getSampleText(langCode: string, difficulty: Difficulty = "medium"): string {
  const lang = sampleTexts[langCode];
  if (!lang) return "";
  const pool = lang[difficulty] ?? lang.medium;
  return pool[Math.floor(Math.random() * pool.length)];
}

/**
 * Deterministic pick (always the first entry in the pool) for use in the very first
 * client/server render, so the statically-generated HTML contains real sample text
 * without a random-vs-random hydration mismatch between server and client.
 */
export function getInitialSampleText(langCode: string, difficulty: Difficulty = "medium"): string {
  const lang = sampleTexts[langCode];
  if (!lang) return "";
  const pool = lang[difficulty] ?? lang.medium;
  return pool[0] ?? "";
}

/** Full paragraph pool for a language/difficulty, for the paragraph-switcher UI. */
export function getTextPool(langCode: string, difficulty: Difficulty = "medium"): string[] {
  const lang = sampleTexts[langCode];
  if (!lang) return [];
  return lang[difficulty] ?? lang.medium ?? [];
}

export function wordCount(text: string): number {
  return text.trim().split(/\s+/).filter(Boolean).length;
}
